-- Read-only historical source database supplement for MCP Git `main` commits.
-- Precondition: run docs/history/MCP_MAIN_MERGE_SHA_DATABASE_20261103.sql first.
-- Order: this P01 SQL, then MCP_ALL_MAIN_COMMITS_20261103_P02.sql.
-- No production data is modified by storing this file in GitHub.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS main_commits (
 commit_sha TEXT PRIMARY KEY CHECK(length(commit_sha)=40 AND commit_sha NOT GLOB '*[^0-9a-f]*'),
 history_position_newest_first INTEGER NOT NULL UNIQUE CHECK(history_position_newest_first > 0),
 commit_date_utc TEXT NOT NULL,
 author_login TEXT, author_name TEXT, committer_login TEXT, committer_name TEXT,
 message_subject TEXT NOT NULL, parent_count INTEGER NOT NULL CHECK(parent_count>=0),
 parent_sha_list TEXT NOT NULL, github_url TEXT NOT NULL,
 merge_pr_number INTEGER REFERENCES merged_prs(pr_number),
 sha_classification TEXT NOT NULL CHECK(sha_classification IN ('KNOWN_MERGED_PR_SHA','OTHER_MAIN_REACHABLE_COMMIT_PR_ASSOCIATION_NOT_VERIFIED'))
);
CREATE INDEX IF NOT EXISTS idx_main_commits_utc ON main_commits(commit_date_utc);
CREATE INDEX IF NOT EXISTS idx_main_commits_pr ON main_commits(merge_pr_number);
CREATE VIEW IF NOT EXISTS all_main_commits_linked_to_merges AS SELECT c.*,p.merged_at_utc,p.title AS merged_pr_title FROM main_commits c LEFT JOIN merged_prs p ON p.pr_number = c.merge_pr_number;
COMMIT;
